      `}).join("")}_bindStudentLiveSessionActions(e,n,a,o){e.querySelectorAll(".slot-selection-box").forEach(l=>{l.addEventListener("click",()=>{let u=l.dataset.paperId,p=l.dataset.slotId;this._studentSelectedSlotMap=this._studentSelectedSlotMap||new Map,this._studentSelectedSlotMap.set(u,p);let f=e.querySelector("#papers-tab-live-content");f&&(f.innerHTML=this._buildStudentLiveSessionsHTML(n,a,o,o.examYear||"2027 A/L",o.examYear||"2027 A/L"),this._bindStudentLiveSessionActions(e,n,a,o))})}),e.querySelectorAll(".btn-register-session-slot").forEach(l=>{l.addEventListener("click",async u=>{if(u.stopPropagation(),!this.checkSubscriptionAccess("Paper Slot Registration"))return;let p=l.dataset.paperId,f=l.dataset.slotId;l.disabled=!0,l.innerHTML=`
